 std::mt19937_64 rng(130);std::string s(n,'a'),t(n,'a');
 if(pattern!=1)for(char&c:s)c='a'+rng()%26;t=s;
 if(pattern==2||pattern==5)t[n/2]='!';if(pattern==3||pattern==6)t[n-1]='!';if(pattern==4||pattern==7)t[n*3/4]='!';
 if(pattern==8){t[0]='!';t[n-1]='!';}
 if(pattern==9){s=std::string(n,'a');t=s;t[0]='b';t[n-1]='!';}
 RollingHash a(s,1000000007),b(t,1000000007);std::uint64_t check=0;
 const auto begin=std::chrono::steady_clock::now();
 for(std::size_t i=0;i<q;++i){std::size_t l=0,ol=0;
   if(pattern==0){l=i%n;ol=(i*3959+17)%n;}
   else if(pattern==8){l=i%(n/4)+1;ol=l;}
   else if(pattern==9){l=0;ol=i%(n/4)+1;}
