#define SKIP_RUNTIME_CHECKS
#include SOURCE
#include <atomic>
#include <chrono>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <limits>
#include <random>
#include <string>
#include <vector>
struct Query{std::size_t l,ol,cap;};
template<int Op> [[gnu::noinline]] static std::uint64_t run(const RollingHash&a,const RollingHash&b,std::size_t n,const std::vector<Query>&qs){std::uint64_t sum=0;for(const auto&q:qs){if constexpr(Op==0)sum+=a.lcp(q.l,b,q.ol,q.cap);else sum+=a.compare(q.l,n,b,q.ol,n)+1;}return sum;}
int main(int argc,char**argv){if(argc!=4)return 1;std::size_t n=std::strtoull(argv[1],nullptr,10);int mode=std::atoi(argv[2]);std::size_t count=std::strtoull(argv[3],nullptr,10);std::mt19937_64 rng(130);std::string s(n,'a'),t(n,'a');if(mode!=1&&mode!=9&&mode!=11)for(char&c:s)c=static_cast<char>('a'+rng()%26);t=s;if(mode==2||mode==5)t[n/2]='!';if(mode==3||mode==6)t[n-1]='!';if(mode==4||mode==7)t[n*3/4]='!';if(mode==8){t[0]='!';t[n-1]='!';}if(mode==9){t[0]='b';t[n-1]='!';}RollingHash a(s,1000000007),b(t,1000000007);std::vector<Query>qs(count);for(std::size_t i=0;i<count;++i){auto&q=qs[i];q={0,0,std::numeric_limits<std::size_t>::max()};if(mode==0||mode>=10){q.l=i%n;q.ol=(i*3959+17)%n;}else if(mode==8){q.l=i%(n/4)+1;q.ol=q.l;}else if(mode==9){q.l=0;q.ol=i%(n/4)+1;}else if(mode<5){q.l=i%(n/4+1);q.ol=q.l;}if(mode==10||mode==11)q.cap=1;if(mode==12){constexpr std::size_t caps[]={0,1,2,3,4,31,32,1024,std::numeric_limits<std::size_t>::max()};q.cap=caps[i%9];}}
std::uint64_t sum=run<OP>(a,b,n,qs);auto begin=std::chrono::steady_clock::now();for(int i=0;i<4;++i){sum+=run<OP>(a,b,n,qs);std::atomic_signal_fence(std::memory_order_seq_cst);}auto end=std::chrono::steady_clock::now();std::printf("%jd %ju\n",static_cast<std::intmax_t>(std::chrono::duration_cast<std::chrono::nanoseconds>(end-begin).count()),static_cast<std::uintmax_t>(sum));}

